function dyadic_certificate(q = a/b in lowest terms):
    k <- 0; d <- b
    while d is even:
        d <- d / 2; k <- k + 1
    if d == 1:
        return (k, a * 2^k / b)   # integer witness m, with m = 2^k q
    else:
        return NONE               # q not dyadic

