from fractions import Fraction
from typing import Optional, Tuple

def dyadic_certificate(q: Fraction) -> Optional[Tuple[int, int]]:
    """Return (k, m) with (m:Q) = 2^k * q and m in Z, else None."""
    b = q.denominator
    k = 0
    while b % 2 == 0:
        b //= 2
        k += 1
    if b != 1:
        return None
    m = q * (2 ** k)
    return k, int(m)

from fractions import Fraction
from typing import List

def v2_den(q: Fraction) -> int:
    b, k = q.denominator, 0
    while b % 2 == 0:
        b //= 2; k += 1
    return k

def escapee(S: List[Fraction]) -> Fraction:
    """A dyadic number outside the subgroup generated by S."""
    N = max((v2_den(s) for s in S), default=0)
    return Fraction(1, 2 ** (N + 1))

from fractions import Fraction
from typing import Tuple

def colim_eval(level: int, value: int) -> Fraction:
    """Element (level, value) of colim(Z --x2--> ...) as value/2^level."""
    return Fraction(value, 2 ** level)

def colim_equal(a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    (n1, m1), (n2, m2) = a, b
    return m1 * (2 ** n2) == m2 * (2 ** n1)
